SELECT FROM department d LEFT JOIN doctor doc ON doc.department_id = d.id
AND d.name LIKE CONCAT('%', #{name}, '%') AND d.status = #{status}
GROUP BY d.id, d.name, d.description, d.sort_order, d.status, d.created_at, d.updated_at ORDER BY d.sort_order ASC, d.id ASC

SELECT EXISTS(
    SELECT 1 FROM department
    WHERE name = #{name}
    AND id != #{excludeId}
)

